def strict_zip(left, right):
    from itertools import zip_longest
    missing = object()
    out = []
    for a, b in zip_longest(left, right, fillvalue=missing):
        if a is missing or b is missing:
            raise ValueError("length mismatch")
        out.append((a, b))
    return out

